ATH = {"author": "Athanasius of Alexandria", "work": "On the Incarnation of the Word", "translator": "Archibald Robertson (Nicene and Post-Nicene Fathers II.4, 1892)", "source": "https://www.newadvent.org/fathers/2802.htm", "kind": "church", "who": "Athanasius (c. 296–373), bishop of Alexandria, the great defender of the Council of Nicaea", "when": "Alexandria, c. 318 or c. 335"}
